export function gameResult(game,answers){
 if(answers[game.id]==='NSP')return {status:'NSP',answered:0,correct:0,total:game.items.length};
 const values=game.items.map((_,i)=>answers[game.id+'_'+i]);
 const answered=values.filter((v,i)=>typeof v==='string'&&game.items[i].options[Number(v)]!==undefined&&/^\d+$/.test(v)).length;
 const correct=values.filter((v,i)=>v===game.items[i].answer).length;
 return {status:answered===0?'NR':answered===game.items.length?'done':'partial',answered,correct,total:game.items.length};
}
export function gameHtml(game,answers){
 const r=gameResult(game,answers);
 return `<p class="eyebrow">${game.id} · Mini-jeu · ${esc(game.kind)}</p><h1 id="page-title" tabindex="-1">${esc(game.title)}</h1><p class="lead">${esc(game.instruction)}</p><div class="game-cards">${game.items.map((it,i)=>`<div class="game-card">${['choix','tri'].includes(game.kind)?`<fieldset><legend><span class="pill">${i+1}</span> ${esc(it.label)}</legend>${it.options.map((o,j)=>`<label class="option"><input type="radio" name="${game.id}_${i}" value="${j}" ${answers[game.id+'_'+i]===String(j)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</fieldset>`:`<label for="${game.id}_${i}"><span class="pill">${i+1}</span> ${esc(it.label)}</label><select id="${game.id}_${i}" name="${game.id}_${i}"><option value="">${game.kind==='ordre'?'Choisir une place':'Choisir une réponse'}</option>${it.options.map((o,j)=>`<option value="${j}" ${answers[game.id+'_'+i]===String(j)?'selected':''}>${esc(o)}</option>`).join('')}</select>`}</div>`).join('')}</div><p id="game-progress" role="status">${r.status==='NSP'?'Vous avez indiqué « Je ne sais pas ».':r.answered+' / '+r.total+' cartes renseignées'}</p><button id="game-unknown" class="secondary small" type="button">Je ne sais pas pour ce mini-jeu</button><details><summary>Comment cela s’est-il passé ? (facultatif)</summary><label for="${game.id}_confidence">Vous êtes…</label><select id="${game.id}_confidence" name="${game.id}_confidence"><option value="">Choisir</option>${['Sûr de moi','Hésitant','Au hasard'].map(v=>`<option ${answers[game.id+'_confidence']===v?'selected':''}>${v}</option>`).join('')}</select><label for="${game.id}_help">Pour répondre, avez-vous reçu de l’aide ?</label><select id="${game.id}_help" name="${game.id}_help"><option value="">Choisir</option>${['Sans aide','Consigne expliquée','Aide pour répondre'].map(v=>`<option ${answers[game.id+'_help']===v?'selected':''}>${v}</option>`).join('')}</select></details><p class="muted">Les corrections seront discutées avec l’animateur. Vous pouvez passer et revenir.</p>`;
}
export function gamesDetail(answers){return games.map(g=>{const r=gameResult(g,answers);return `<details class="card"><summary>${esc(g.domain+' · '+g.title)} — ${r.status==='NSP'?'Ne sait pas':r.status==='NR'?'Non renseigné':r.correct+' correct(s) sur '+r.answered+' réponse(s), '+(r.total-r.answered)+' manquante(s)'}</summary>${g.items.map((it,i)=>`<p><strong>${esc(it.label)}</strong><br>Réponse : ${esc(it.options[answers[g.id+'_'+i]]??'Sans réponse')}<br>Attendu : ${esc(it.options[Number(it.answer)])}</p>`).join('')}<p>Confiance : ${esc(answers[g.id+'_confidence']||'Non renseignée')} · Aide : ${esc(answers[g.id+'_help']||'Non renseignée')}</p></details>`;}).join('');}
